# Harmonia Dark High Contrast
# generated by harmonia-terminal, do not edit

& {
  $e = [char]27

  try {
    if (Get-Module PSReadLine) {
      $rlVersion = (Get-Module PSReadLine).Version
      $colors = @{
        Default = "$e[39m"
        Comment = "$e[38;2;130;136;149m"
        Keyword = "$e[38;2;194;150;232m"
        String = "$e[38;2;160;222;192m"
        Number = "$e[38;2;230;186;120m"
        Operator = "$e[38;2;208;206;224m"
        Variable = "$e[38;2;121;212;210m"
        Parameter = "$e[38;2;150;221;213m"
        Command = "$e[38;2;111;163;217m"
        Type = "$e[38;2;156;192;255m"
        Member = "$e[38;2;230;234;246m"
        Emphasis = "$e[38;2;122;168;217m"
        Error = "$e[38;2;255;126;138m"
        ContinuationPrompt = "$e[38;2;124;130;163m"
        Selection = "$e[39;48;2;53;66;112m"
      }
      if ($rlVersion -ge [version]'2.1') {
        $colors.InlinePrediction = "$e[38;2;130;136;149m"
      }
      if ($rlVersion -ge [version]'2.2') {
        $colors.ListPrediction = "$e[38;2;122;168;217m"
        $colors.ListPredictionSelected = "$e[48;2;58;62;107m"
      }
      if ($rlVersion -ge [version]'2.3') {
        $colors.ListPredictionTooltip = "$e[38;2;130;136;149m"
      }
      Set-PSReadLineOption -Colors $colors -ErrorAction Stop
    }
  } catch {}

  try {
    if ($PSVersionTable.PSVersion -ge [version]'7.2') {
      $PSStyle.Formatting.TableHeader = "$e[1;38;2;156;192;255m"
      $PSStyle.Formatting.FormatAccent = "$e[1;38;2;156;192;255m"
      $PSStyle.Formatting.CustomTableHeaderLabel = "$e[3;38;2;156;192;255m"
      $PSStyle.Formatting.Error = "$e[38;2;255;126;138m"
      $PSStyle.Formatting.ErrorAccent = "$e[1;38;2;255;126;138m"
      $PSStyle.Formatting.Warning = "$e[38;2;255;201;121m"
      $PSStyle.Formatting.Verbose = "$e[38;2;122;168;217m"
      $PSStyle.Formatting.Debug = "$e[38;2;130;136;149m"
      $formatting = $PSStyle.Formatting.PSObject.Properties
      if ($formatting['FeedbackName']) { $PSStyle.Formatting.FeedbackName = "$e[38;2;122;168;217m" }
      if ($formatting['FeedbackText']) { $PSStyle.Formatting.FeedbackText = "$e[39m" }
      if ($formatting['FeedbackAction']) { $PSStyle.Formatting.FeedbackAction = "$e[38;2;160;222;192m" }
      $PSStyle.Progress.Style = "$e[38;2;11;12;18;48;2;122;168;217m"
      $PSStyle.FileInfo.Directory = "$e[1;38;2;122;168;217m"
      $PSStyle.FileInfo.SymbolicLink = "$e[38;2;121;212;210m"
      $PSStyle.FileInfo.Executable = "$e[38;2;160;222;192m"
      $PSStyle.FileInfo.Extension['.zip'] = "$e[38;2;230;186;120m"
      $PSStyle.FileInfo.Extension['.tgz'] = "$e[38;2;230;186;120m"
      $PSStyle.FileInfo.Extension['.gz'] = "$e[38;2;230;186;120m"
      $PSStyle.FileInfo.Extension['.tar'] = "$e[38;2;230;186;120m"
      $PSStyle.FileInfo.Extension['.nupkg'] = "$e[38;2;230;186;120m"
      $PSStyle.FileInfo.Extension['.cab'] = "$e[38;2;230;186;120m"
      $PSStyle.FileInfo.Extension['.7z'] = "$e[38;2;230;186;120m"
      $PSStyle.FileInfo.Extension['.ps1'] = "$e[38;2;194;150;232m"
      $PSStyle.FileInfo.Extension['.psd1'] = "$e[38;2;194;150;232m"
      $PSStyle.FileInfo.Extension['.psm1'] = "$e[38;2;194;150;232m"
      $PSStyle.FileInfo.Extension['.ps1xml'] = "$e[38;2;194;150;232m"
      $PSStyle.FileInfo.Extension['.js'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.jse'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.vbs'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.vbe'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.wsf'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.wsh'] = "$e[39m"
      $formatFile = Join-Path $PSScriptRoot 'harmonia.format.ps1xml'
      if (Test-Path $formatFile) { Update-FormatData -PrependPath $formatFile }
    }
  } catch {}
}
